CREATE TABLE macro_history_request(id uuid PRIMARY KEY,job_id uuid NOT NULL REFERENCES ingestion_job(id),series_id text NOT NULL REFERENCES macro_series(id),url text NOT NULL,http_status integer,sha256 text,response_id uuid REFERENCES official_response(id),start_period date NOT NULL,end_period date NOT NULL,updated_after timestamptz,include_history boolean NOT NULL,source_last_modified text,response_prepared text,raw_valid_from text,vintage_verified boolean NOT NULL DEFAULT false CHECK(NOT vintage_verified),dataset_action text,observations integer NOT NULL DEFAULT 0,started_at timestamptz NOT NULL DEFAULT clock_timestamp(),finished_at timestamptz,error text);
CREATE TABLE macro_history_version(id uuid PRIMARY KEY,series_id text NOT NULL REFERENCES macro_series(id),observation_date date NOT NULL,value numeric,observation_status text,action text NOT NULL CHECK(action IN('Replace','Append','Information','Delete')),version integer NOT NULL,content_hash text NOT NULL,response_id uuid NOT NULL REFERENCES official_response(id),request_id uuid NOT NULL REFERENCES macro_history_request(id),collected_at timestamptz NOT NULL DEFAULT clock_timestamp(),source_published_at timestamptz,source_vintage_at timestamptz,UNIQUE(series_id,observation_date,version),CHECK(source_vintage_at IS NULL));
CREATE INDEX macro_history_asof ON macro_history_version(series_id,observation_date,collected_at DESC);
CREATE FUNCTION immutable_macro_history() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Macro versions and raw responses are immutable';END $$;
CREATE TRIGGER macro_history_immutable BEFORE UPDATE OR DELETE ON macro_history_version FOR EACH ROW EXECUTE FUNCTION immutable_macro_history();
